def wrap_html(text):
    return f'<div class="bg-white dark:bg-slate-100 text-gray-900 border border-gray-400 p-5 md:p-8 rounded shadow-sm font-sans text-base leading-loose max-w-3xl mx-auto whitespace-pre-line">\n{text}\n</div>'

for day, file_path in files.items():
    if not os.path.exists(file_path):
        print(f"File not found: {file_path}")
        continue
    with open(file_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    
    for i, sub in enumerate(data.get("subSections", [])):
        if i < len(texts[day]):
            sub["passage"] = wrap_html(texts[day][i])
    
    with open(file_path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"Updated {file_path}")
